import * as React from "react";
import { PageParamsProvider as PageParamsProvider__ } from "@plasmicapp/react-web/lib/host";
import GlobalContextsProvider from "../../../components/plasmic/sayban/PlasmicGlobalContextsProvider";
import { StyleTokensProvider } from "../../../components/plasmic/sayban/PlasmicStyleTokensProvider";

import PanelComponent from "../../../components/Panel";
import { useRouter } from "next/router";
import { PlasmicQueryDataProvider } from "@plasmicapp/react-web/lib/query";
import { usePanelAuthGuard } from "@/lib/usePanelAuthGuard";
import { panelParamsFromRouter } from "@/lib/panelRouteParams";
import { usePanelLocation } from "@/lib/usePanelLocation";

function PanelPage() {
  // Blocks panel content for signed-out visitors arriving via Back or a direct
  // URL, and redirects them to the panel login.
  const allowed = usePanelAuthGuard();
  const router = useRouter();
  // Catch-all Back/`replace` can update the address bar without `router.asPath`.
  const asPath = usePanelLocation();
  const params = panelParamsFromRouter(router.query, asPath);

  return (
    <GlobalContextsProvider>
      <PlasmicQueryDataProvider>
        <PageParamsProvider__
          route={asPath}
          params={params}
          query={params}
        >
          <StyleTokensProvider>
            {allowed ? <PanelComponent /> : null}
          </StyleTokensProvider>
        </PageParamsProvider__>
      </PlasmicQueryDataProvider>
    </GlobalContextsProvider>
  );
}

export default PanelPage;
